import{_ as s,o as t,c as a,ah as i}from"./chunks/framework.ChH6X6u6.js";const f=JSON.parse('{"title":"Pilotage","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/direction/pilotage.md","filePath":"src/guide/direction/pilotage.md"}'),r={name:"guide/direction/pilotage.md"};function n(l,e,o,u,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="pilotage" tabindex="-1">Pilotage <a class="header-anchor" href="#pilotage" aria-label="Permalink to &quot;Pilotage&quot;">​</a></h1><p>La page <strong>Pilotage</strong> donne les chiffres de l&#39;établissement — effectifs, résultats, assiduité, finances — et permet de les regarder d&#39;aussi près que nécessaire : un site, un niveau, une classe. Elle s&#39;ouvre depuis l&#39;espace <strong>Direction</strong> du menu, ou depuis <strong>Accueil</strong> pour un administrateur.</p><p>Elle fait partie du module <strong>Pilotage</strong>, comme les profils de <a href="/era-guide/guide/direction/">direction</a>.</p><h2 id="choisir-ce-que-l-on-regarde" tabindex="-1">Choisir ce que l&#39;on regarde <a class="header-anchor" href="#choisir-ce-que-l-on-regarde" aria-label="Permalink to &quot;Choisir ce que l&#39;on regarde&quot;">​</a></h2><p>L&#39;<strong>année</strong> est celle choisie dans l&#39;en-tête de l&#39;application, comme sur les autres écrans de consultation. La page ajoute trois filtres, du plus large au plus fin :</p><ol><li>le <strong>site</strong> ;</li><li>le <strong>niveau</strong> (6e, 5e…) ;</li><li>la <strong>classe</strong>.</li></ol><p>Changer un filtre remet à zéro ceux qui sont plus fins que lui : choisir un autre site efface le niveau et la classe.</p><div class="info custom-block"><p class="custom-block-title">Direction de site</p><p>Une direction de site ne voit que ses sites. Si elle n&#39;en dirige qu&#39;un, il est déjà choisi et le filtre de site n&#39;apparaît pas ; son nom figure sous le titre. Si elle en dirige plusieurs, elle les voit ensemble, puis site par site.</p></div><h2 id="les-chiffres" tabindex="-1">Les chiffres <a class="header-anchor" href="#les-chiffres" aria-label="Permalink to &quot;Les chiffres&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scolarité</th><th>Finances</th></tr></thead><tbody><tr><td>Élèves inscrits</td><td>Montant dû</td></tr><tr><td>Résultats moyens</td><td>Montant encaissé</td></tr><tr><td>Taux d&#39;absentéisme</td><td>Taux de recouvrement</td></tr><tr><td>Occupation internat</td><td>Montant décaissé</td></tr><tr><td></td><td>Flux de trésorerie net</td></tr></tbody></table><p>Ce sont les mêmes indicateurs que sur le <a href="/era-guide/guide/admin/tableau-de-bord.html">tableau de bord</a>, calculés de la même façon.</p><p>Les <strong>dépenses</strong> et l&#39;<strong>internat</strong> appartiennent à un site, pas à un niveau ni à une classe : dès qu&#39;un niveau ou une classe est choisi, ces chiffres affichent « — », et une ligne sous les indicateurs le rappelle.</p><h2 id="descendre-d-un-cran" tabindex="-1">Descendre d&#39;un cran <a class="header-anchor" href="#descendre-d-un-cran" aria-label="Permalink to &quot;Descendre d&#39;un cran&quot;">​</a></h2><p>Le tableau sous les chiffres détaille le périmètre choisi un cran plus finement :</p><ul><li>tout l&#39;établissement → <strong>par site</strong> ;</li><li>un site → <strong>par niveau</strong> ;</li><li>un niveau → <strong>par classe</strong>.</li></ul><p>Cliquez sur le nom d&#39;une ligne pour descendre : le filtre se met à jour et le tableau détaille le cran suivant. Pour une classe seule, il n&#39;y a plus rien à détailler.</p><h2 id="mois-par-mois" tabindex="-1">Mois par mois <a class="header-anchor" href="#mois-par-mois" aria-label="Permalink to &quot;Mois par mois&quot;">​</a></h2><p>Deux graphiques suivent l&#39;année depuis la rentrée jusqu&#39;au mois en cours :</p><ul><li><strong>encaissements et décaissements</strong> de chaque mois — les décaissements disparaissent sous le site, pour la même raison que plus haut ;</li><li><strong>taux d&#39;absentéisme</strong> de chaque mois, à partir des appels faits.</li></ul><p>Un graphique sans aucune donnée (par exemple avant les premiers appels) l&#39;indique simplement.</p><h2 id="classes-en-sureffectif" tabindex="-1">Classes en sureffectif <a class="header-anchor" href="#classes-en-sureffectif" aria-label="Permalink to &quot;Classes en sureffectif&quot;">​</a></h2><p>La dernière section liste les élèves affectés à une classe déjà pleine, dans le périmètre choisi : la classe et son site, l&#39;effectif atteint (<code>31/30</code>), s&#39;il s&#39;agissait d&#39;une admission ou d&#39;une mobilité, le <strong>motif</strong> saisi, l&#39;élève, la personne qui a forcé l&#39;affectation et la date. Voir <a href="/era-guide/guide/direction/#classes-en-sureffectif">Direction → Classes en sureffectif</a>.</p><h2 id="exporter" tabindex="-1">Exporter <a class="header-anchor" href="#exporter" aria-label="Permalink to &quot;Exporter&quot;">​</a></h2><p><strong>Exporter le tableur</strong> télécharge un fichier CSV avec le tableau affiché et la ligne <strong>Total</strong> du périmètre choisi — les mêmes filtres que la page.</p>',24)])])}const g=s(r,[["render",n]]);export{f as __pageData,g as default};
